78	    public Optional<Equipment> findEquipmentForUpdate(String equipmentId) {
79	        List<Equipment> rows = jdbc.query(
80	                "SELECT equipment_id, maintenance_period_minutes, version FROM equipment"
81	                        + " WHERE equipment_id = ? FOR UPDATE",
82	                EQUIPMENT_MAPPER, equipmentId);
83	        return rows.stream().findFirst();
