93	        jdbc.update("INSERT INTO reading (equipment_id, reading_id, sampled_at, cumulative_minutes,"
94	                        + " revision_no, created_at, updated_at) VALUES (?, ?, ?, ?, 1, ?, ?)",
95	                reading.equipmentId(), reading.readingId(), utc(reading.sampledAt()),
96	                reading.cumulativeMinutes(), utc(createdAt), utc(createdAt));
97	    }
98	
99	    public Optional<Reading> findReading(String equipmentId, String readingId) {
100	        List<Reading> rows = jdbc.query(
101	                "SELECT equipment_id, reading_id, sampled_at, cumulative_minutes, revision_no"
102	                        + " FROM reading WHERE equipment_id = ? AND reading_id = ?",
103	                READING_MAPPER, equipmentId, readingId);
104	        return rows.stream().findFirst();
105	    }
106	
107	    public Optional<Reading> findReadingAt(String equipmentId, Instant sampledAt) {
108	        List<Reading> rows = jdbc.query(
109	                "SELECT equipment_id, reading_id, sampled_at, cumulative_minutes, revision_no"
110	                        + " FROM reading WHERE equipment_id = ? AND sampled_at = ?",
111	                READING_MAPPER, equipmentId, utc(sampledAt));
112	        return rows.stream().findFirst();
