 * @param maintenancePeriodMinutes  保养周期（分钟），登记后不可修改
 * @param version                   设备当前版本号，初始 1
 */
public record EquipmentResponse(
        String equipmentId,
        long maintenancePeriodMinutes,
        long version) {
}

