package com.example.starter.maintenance.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 认证读数请求：将指定读数标记为设备当前已认证读数（同设备同时仅一个当前已认证读数）。
 *
 * @param requestId        全局唯一请求标识（幂等键）
 * @param expectedVersion  设备期望版本号，与当前版本不一致时返回 409
 */
public record CertifyReadingRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion) {
}

package com.example.starter.maintenance.api.dto;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 创建保养工单请求：冻结基线读数快照与允许登记的 UTC 左闭右开窗口。
 *
 * @param workOrderKey       工单幂等键；同键同参重放，异参 409，失败不占键
 * @param expectedVersion    设备期望版本号
 * @param workOrderId        工单标识，设备内唯一
 * @param baselineReadingId  基线读数标识，须为设备当前已认证读数
 * @param windowStart        允许登记窗口起点（UTC，含）
 * @param windowEnd          允许登记窗口终点（UTC，不含），必须严格晚于起点
 */
public record CreateWorkOrderRequest(
        @NotBlank String workOrderKey,
        @NotNull Long expectedVersion,
        @NotBlank String workOrderId,
        @NotBlank String baselineReadingId,
        @NotNull Instant windowStart,
        @NotNull Instant windowEnd) {
}

package com.example.starter.maintenance.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 开始保养工单请求：仅未开始（CREATED）工单可开始。
 *
 * @param workOrderKey      工单幂等键
 * @param expectedVersion   设备期望版本号
 * @param workOrderVersion  工单期望版本号（未开始工单为 1）
 */
public record StartWorkOrderRequest(
        @NotBlank String workOrderKey,
        @NotNull Long expectedVersion,
        @NotNull Long workOrderVersion) {
}

package com.example.starter.maintenance.api.dto;

import java.time.Instant;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 工单窗口内批量登记的单条读数。
 *
 * @param readingId          读数标识，设备内唯一，批次内亦不可重复
 * @param sampledAt          UTC 采样时刻，必须落在工单窗口 [windowStart, windowEnd) 内
 * @param cumulativeMinutes  累计工时（分钟），不得低于基线
 */
public record WorkOrderReadingItem(
        @NotBlank String readingId,
        @NotNull Instant sampledAt,
        @NotNull @PositiveOrZero Long cumulativeMinutes) {
}

package com.example.starter.maintenance.api.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

/**
 * 工单进行期间批量登记读数请求：先按最终读数序列、窗口、基线与版本整体预校验，
 * 任一越窗、倒退或版本失配返回 422，全部读数与工单状态回滚。
 *
 * @param workOrderKey      工单幂等键，指纹含读数摘要
 * @param expectedVersion   设备期望版本号
 * @param workOrderVersion  工单期望版本号
 * @param readings          本批次读数（至少一条）
 */
public record RegisterWorkOrderReadingsRequest(
        @NotBlank String workOrderKey,
        @NotNull Long expectedVersion,
        @NotNull Long workOrderVersion,
        @NotEmpty @Valid List<WorkOrderReadingItem> readings) {
}

package com.example.starter.maintenance.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 关闭保养工单请求：写入不可变保养状态快照（基线、最后有效读数、关闭时刻）。
 *
 * @param workOrderKey      工单幂等键
 * @param expectedVersion   设备期望版本号
 * @param workOrderVersion  工单期望版本号
 */
public record CloseWorkOrderRequest(
        @NotBlank String workOrderKey,
        @NotNull Long expectedVersion,
